using System;
using System.Collections;
using UnityEngine;
using UnityEngine.InputSystem;
public sealed class FpsMatrixVerifier:N5Runner
{
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Init()=>N5Args.Start<FpsMatrixVerifier>("-verify-fps-matrix");
 protected override string Evidence=>N5Args.Value("-verify-output","Validation/N5-TD-fps-matrix.txt");
 protected override IEnumerator Tests(){yield return ContinueGame();Check(Motor.hasDoubleJump&&Player.GetComponent<PlayerDash>().hasDash,"fixture owned abilities via normal Continue");foreach(int fps in new[]{30,60,120,144}){Application.targetFrameRate=fps;yield return new WaitForSecondsRealtime(.5f);
   yield return RouteTo("A03");yield return Segment("G-D-walk",new Vector2(15.2f,5.81f),false,false,1,()=>Body.position.x>17.5f,fps);yield return Segment("G-D-dash",new Vector2(15.2f,5.81f),false,true,1,()=>Body.position.x>17.5f,fps);
   yield return RouteTo("A05");var platform=GameObject.Find("A05_PracticeA").GetComponent<BoxCollider2D>().bounds;Vector2 start=new Vector2(platform.max.x-.7f,platform.max.y+.81f);yield return Segment("A05-normal",start,false,false,.9f,()=>Body.position.x>=GameObject.Find("A05_PracticeB").GetComponent<BoxCollider2D>().bounds.min.x&&Motor.Grounded,fps);yield return Segment("A05-dash",start,false,true,.9f,()=>Body.position.x>=GameObject.Find("A05_PracticeB").GetComponent<BoxCollider2D>().bounds.min.x&&Motor.Grounded,fps);
   yield return RouteTo("B01");yield return Segment("G-J-normal",new Vector2(23.5f,1.81f),false,false,.95f,()=>Body.position.x>=26&&Body.position.y-.8f>=4.55f,fps);yield return Segment("G-J-double",new Vector2(23.5f,1.81f),true,false,.95f,()=>Body.position.x>=26&&Body.position.y-.8f>=4.55f,fps);
   yield return RouteTo("B04");yield return Segment("B04",new Vector2(19.1f,3.81f),true,false,.95f,()=>Body.position.x>=23&&Body.position.y-.8f>=5.7f,fps);
   yield return RouteTo("C02");yield return Segment("C02-double",new Vector2(9.3f,3.81f),true,false,.95f,()=>Body.position.x>=12&&Body.position.x<=16.4f&&Motor.Grounded&&Mathf.Abs(Body.position.y-7.6f)<.1f,fps);yield return Segment("C02-dash",new Vector2(15.3f,7.61f),false,true,.9f,()=>Body.position.x>=21&&Body.position.x<=25.4f&&Motor.Grounded&&Mathf.Abs(Body.position.y-7.6f)<.1f,fps);
   yield return RouteTo("C03");yield return Segment("C03-cover",new Vector2(19,1.81f),true,true,1.1f,()=>Body.position.x>22,fps);
  }
 }
 IEnumerator RouteTo(string target){string[] edges={"A01 A02","A02 A03","A03 A04","A04 A05","A03 B01","B01 B02","B02 B03","B03 B04","B01 B05","B05 C01","C01 C02","C02 C03","C03 C04"};var queue=new System.Collections.Generic.Queue<string>();var parents=new System.Collections.Generic.Dictionary<string,string>();string start=RoomSession.Instance.CurrentRoomId;queue.Enqueue(start);parents[start]=null;while(queue.Count>0){string at=queue.Dequeue();if(at==target)break;foreach(string edge in edges){var e=edge.Split(' ');string next=e[0]==at?e[1]:e[1]==at?e[0]:null;if(next!=null&&!parents.ContainsKey(next)){parents[next]=at;queue.Enqueue(next);}}}if(!parents.ContainsKey(target))throw new Exception("matrix route unavailable "+target);var path=new System.Collections.Generic.Stack<string>();for(string at=target;at!=start;at=parents[at])path.Push(at);while(path.Count>0)yield return PhysicalDoor(path.Pop());yield return Ready();}
 IEnumerator Segment(string name,Vector2 start,bool twice,bool dash,float seconds,Func<bool> success,int fps){yield return Keys();PlaceForAuthorizedSetup(start);yield return new WaitForSecondsRealtime(.2f);string room=RoomSession.Instance.CurrentRoomId;double begun=Time.realtimeSinceStartupAsDouble,end=begun+seconds;int frames=0;float maxX=start.x,maxY=start.y-.8f;bool second=false,release=false,dashed=false;bool walk=name=="G-D-walk";while(Time.realtimeSinceStartupAsDouble<end){double t=Time.realtimeSinceStartupAsDouble-begun;var keys=new System.Collections.Generic.List<Key>{Key.RightArrow};if(!walk){if(t<.28||!twice||release)keys.Add(Key.Z);if(t>=.28&&twice&&!second){keys.Remove(Key.Z);release=true;second=true;}else if(release){keys.Add(Key.Z);}if(dash&&t>=.30&&!dashed){keys.Add(Key.C);dashed=true;}}UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,new UnityEngine.InputSystem.LowLevel.KeyboardState(keys.ToArray()));maxX=Mathf.Max(maxX,Body.position.x);maxY=Mathf.Max(maxY,Body.position.y-.8f);frames++;if(RoomSession.Instance.Respawning||RoomSession.Instance.CurrentRoomId!=room)break;yield return null;}double measuredSeconds=Time.realtimeSinceStartupAsDouble-begun;yield return Keys();yield return new WaitForSecondsRealtime(.15f);bool passed=RoomSession.Instance.CurrentRoomId==room&&!RoomSession.Instance.Respawning&&success();lines.Add($"CELL {name} targetfps={fps} actualfps={frames/measuredSeconds:F2} success={passed} maxHorizontal={maxX-start.x:F3} maxFeet={maxY:F3} final={Body.position}");yield return Ready();}
}
